import React, { useState, activePage } from 'react';
import './gerenciamento-assuntos.css';
import { FaHome, FaMedal, FaUser, FaEllipsisH, FaVolumeUp, FaVolumeMute, FaStar, FaHeart } from 'react-icons/fa'
import { Link } from 'react-router-dom';
import assuntosMock from '../../data/assuntos-mock'
import logo from '../../assets/logo.png';

const GerenciamentoAssuntos = () => {
  const [searchTerm, setSearchTerm] = useState('');

  // Filtro de busca
  const assuntosFiltrados = assuntosMock.filter((assunto) =>
    assunto.nome.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleNavigation = (page) => {
    setActivePage(page);
  };

  return (
    <div className="gerenciamento-assuntos-page">
      {/* Sidebar Esquerdo */}
       <nav className="sidebar-left">
              <div className="logo-container">
                <img src={logo} alt="FisioGame Logo" className="logo" />
                <h1 className="content-left">FISIOGAME</h1>
              </div>
              <div className="menu-buttons">
                <button
                  className={`menu-item ${activePage === 'DashboardPage' ? 'selected' : ''}`}
                  onClick={() => handleNavigation('DashboardPage')}
                >
                  <FaHome size={24} /> Início
                </button>
                <button
                  className={`menu-item ${activePage === 'perfil' ? 'selected' : ''}`}
                  onClick={() => handleNavigation('perfil')}
                >
                  <FaUser size={24} /> Perfil
                </button>
                <button
                  className={`menu-item ${activePage === 'mais' ? 'selected' : ''}`}
                  onClick={() => handleNavigation('mais')}
                >
                  <FaEllipsisH size={24} /> Mais
                </button>
              </div>
            </nav>

      {/* Conteúdo principal */}
      <div className="gerenciamento-assuntos-container">
        <header className="content-header">Gerenciamento de Assuntos</header>

        {/* Barra de Pesquisa */}
        <div className="search-bar">
          <input
            type="text"
            placeholder="Buscar Assunto..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
          <FaSearch size={20} className="search-icon" />
        </div>

        {/* Lista de Assuntos */}
        <div className="assuntos-list">
          {assuntosFiltrados.length > 0 ? (
            assuntosFiltrados.map((assunto) => (
              <Link
                key={assunto.id}
                to={`/assunto/${assunto.id}`} // Rota para gerenciamento do assunto
                className="assunto-card"
              >
                {assunto.nome}
              </Link>
            ))
          ) : (
            <p className="no-results">Nenhum assunto encontrado.</p>
          )}
        </div>
      </div>

      {/* Sidebar Direito */}
      <SidebarRight />
    </div>
  );
};

export default GerenciamentoAssuntos;
